WITH matched_keys AS (SELECT order_id, id FROM order_items EXCEPT ALL SELECT order_id, id FROM order_items WHERE unit_price < 300), reconciled AS (SELECT s.* FROM order_items s INNER JOIN matched_keys k ON s.order_id = k.order_id AND s.id = k.id) SELECT s.id, s.product_id, s.unit_price, (SELECT AVG(x.unit_price) FROM order_items x WHERE x.product_id = s.product_id) AS avg_order_item_unit_price FROM reconciled s ORDER BY id DESC NULLS LAST;
